            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'Why did Vera tell Framton the story of the hunting tragedy?', 'option_a' => 'She enjoyed making up romances to startle visitors', 'option_b' => 'She wanted Framton to marry into the family', 'option_c' => 'She believed the story was true', 'option_d' => 'Her aunt ordered her to frighten him', 'correct_option' => 'a'],
