            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'How did the stranger make sure Dan\'l Webster could not jump?', 'option_a' => 'He filled its mouth full of quail shot with a teaspoon', 'option_b' => 'He fed it a heavy meal of flies', 'option_c' => 'He nailed the lattice box shut', 'option_d' => 'He stole the frog during the night', 'correct_option' => 'a'],
